#include <string>

using namespace std;

class Solution {
public:
    int longestDecomposition(string text) {
        int n = text.size(), res = 0;
        string l = "", r = "";
        for (int i = 0; i < n; ++i) {
            l += text[i];
            r = text[n - 1 - i] + r;
            if (l == r) {
                res++;
                l = r = "";
            }
        }
        return res;
    }
};
